"""Build a dependency-free static study site from reviewed local content."""
import json, shutil
from pathlib import Path
R=Path(__file__).resolve().parents[1]
q=json.loads((R/'content/questions.json').read_text(encoding='utf-8'))
notes={}
def add(ids,topic,text,url):
    for i in ids: notes[i]={'topic':topic,'body':text,'source':url}
D='https://docs.databricks.com/aws/en/'
S='https://spark.apache.org/docs/latest/'
add([1,68,112,258,278], 'SQL joins', 'LEFT JOIN keeps every left row; unmatched right columns become NULL. LEFT ANTI keeps only unmatched left rows. LEFT SEMI keeps matching left rows without right-side columns. Multiple right matches can multiply rows.', S+'sql-ref-syntax-qry-select-join.html')
add([2,62,113,240], 'Nested data', 'Arrays: filter(array, x -> condition) keeps elements; transform changes elements; explode creates rows. Structs: select("device.location.city") accesses nested fields; select("device.*") expands one level.', S+'sql-ref-functions-builtin.html')
add([3,15,74,93,241], 'Architecture', 'Classic: control plane hosts workspace UI, orchestration and metadata; driver/workers execute in the customer compute plane. Serverless compute runs in a Databricks-managed compute plane, so keep the architecture type in mind.', D+'getting-started/overview')
add([4,5,9,47,54,69,91,95,98,140,202,203,251], 'Delta Lake', 'Delta = Parquet data + _delta_log transaction metadata. ACID, schema enforcement and version history support reliable batch/streaming on shared data. Schema evolution must be enabled; historical queries also require retained data files.', D+'delta/')
add([6,16,20,100,104,219], 'Delta writes', 'DELETE removes matching rows; UPDATE changes values; INSERT appends. MERGE matches business keys for conditional updates/inserts; WHEN NOT MATCHED BY SOURCE THEN DELETE removes target-only rows. Deduplicate source keys before MERGE.', D+'delta/merge')
add([7,17,19,76,103,122,158,168,221,232,235,265], 'Incremental ingestion', 'Auto Loader uses Structured Streaming and checkpoints to track file progress. COPY INTO skips previously loaded files; force reloading can duplicate rows. File Arrival starts the job; Auto Loader decides which files still need processing.', D+'ingestion/cloud-object-storage/auto-loader/')
add([8,75,160,256,279], 'NULL handling', 'COUNT(*) counts all rows; COUNT(col) excludes NULL; COUNT_IF(col IS NULL) counts missing values. NULL comparisons use IS NULL, not = NULL. <=> is null-safe equality. df.na.drop(subset=["email", "phone"]) drops rows missing either field.', S+'sql-ref-null-semantics.html')
add([10,24,102,159,213,245,273], 'Tables and views', 'Table stores data; ordinary view stores a query; temporary view is session-scoped. Materialized views store precomputed results and refresh them—useful for repeated BI aggregations. A shared, persisted result needs a table or materialized view.', D+'views/')
add([11,22,44,45,61,83,85,89,96,163,176,197,210,226,260], 'Unity Catalog privileges', 'Hierarchy: catalog → schema → table/view. Reading needs USE CATALOG, USE SCHEMA and SELECT. CREATE TABLE enables creation; MODIFY enables writes. MANAGE delegates grants without transferring ownership. Legacy USAGE/DATABASE wording differs from Unity Catalog.', D+'data-governance/unity-catalog/manage-privileges/privileges')
add([12,28,105,111], 'Spark SQL in Python', 'spark.table("catalog.schema.table") returns a DataFrame; spark.sql("SELECT ...") runs SQL and also returns a DataFrame. Transformations are lazy; actions trigger execution. A bare table name is not a SQL query.', D+'pyspark/')
add([13,14,99,106,108,134], 'SQL metadata and DDL', 'DESCRIBE DATABASE EXTENDED shows database metadata and location; DESCRIBE DETAIL shows table storage details. TBLPROPERTIES stores custom metadata. CREATE OR REPLACE replaces the object; IF NOT EXISTS leaves an existing object unchanged.', D+'sql/language-manual/sql-ref-syntax-ddl-create-table-using')
add([18,48,66,114], 'Python control flow', 'Use if day_of_week == 1 and review_period: for both conditions. Define a function with def name(a, b): and return a + b. Python uses indentation; SQL runs through spark.sql(...) or a separate %sql cell.', 'https://docs.python.org/3/tutorial/controlflow.html')
add([21], 'JDBC ingestion', 'USING JDBC connects a table definition to an external database. Supply the JDBC URL and dbtable/query plus driver/authentication as needed. JDBC is a connection interface; CSV/Parquet are file formats.', D+'connect/external-systems/jdbc-logs')
add([23,64,107,165,195,211,212,248,257], 'Managed and external tables', 'Managed tables let Unity Catalog manage storage lifecycle; external tables retain externally managed files after DROP. LOCATION points to external storage. ALTER TABLE ... SET MANAGED preserves table identity; coordinate/restart streaming readers after conversion.', 'https://learn.microsoft.com/en-us/azure/databricks/tables/convert-foreign-managed')
add([25,26,32,33,34,36,42,63,65,80,116,117,120,121,126,138,146,151,173,225], 'Declarative pipelines', 'Expectations: EXPECT records violations; ON VIOLATION DROP ROW discards bad rows; FAIL UPDATE stops the update. Pipeline event logs show dataset-level quality metrics. Streaming tables process incrementally; SQL and Python datasets can coexist in a pipeline.', D+'ldp/expectations')
add([27,37,41,60,128,135,239,252,253,261,264,274], 'Job orchestration', 'Depends on points to upstream tasks; multiple dependencies form a DAG. Use an If/else task for taskValue conditions, and check run-if rules for success/failure branches. Table-update triggers react to table changes; concurrency limits/queueing can delay scheduled runs.', D+'jobs/configure-task')
add([29,50,72,73,79,81,119,124,125,141,154,182,183,204], 'Medallion layers', 'Bronze retains raw source detail plus ingestion metadata; Silver cleans, validates and deduplicates; Gold serves business metrics/aggregations. Layer means data purpose, not a guaranteed row count: joins and explode can increase Silver rows.', D+'lakehouse/medallion')
add([30,31,67,78,115,118], 'Structured Streaming', 'readStream/writeStream define streaming I/O. processingTime="5 seconds" schedules micro-batches; availableNow=True drains available data in one or more batches then stops. Checkpoints persist offsets/state for recovery; use a separate checkpoint per query.', D+'structured-streaming/triggers')
add([35,46,94,97,190], 'Git folders', 'Pull brings remote commits into the working branch; push publishes local commits; clone creates a checkout. Branches isolate changes. Pull requests and protected-branch review are managed at the Git provider.', D+'repos/')
add([38,40,55,82,86,88,90,130,167,220], 'SQL warehouses', 'Auto-stop reduces idle cost; serverless reduces startup/management overhead. Increase warehouse size for heavier individual queries; increase max clusters for concurrent queries. A schedule end date stops future refreshes; auto-stop alone does not cancel schedules.', D+'compute/sql-warehouse/')
add([39], 'UNION', 'UNION removes duplicate full rows; UNION ALL preserves them and avoids deduplication work. Both require compatible column counts/types. If inputs are already disjoint, UNION ALL produces the same rows more efficiently.', D+'sql/language-manual/sql-ref-syntax-qry-select-setops')
add([43,49,77,92,127,148,157,180,191,192,193,207,259,272,275], 'Compute choices', 'Interactive/all-purpose compute suits iterative development; jobs compute suits scheduled execution; serverless manages capacity and reduces idle overhead. Pools reduce classic cluster startup latency. Single-node compute suits small, non-distributed workloads.', D+'compute/')
add([51,52,59,70,101,155,170,187,188,233,280], 'Delta maintenance', 'OPTIMIZE compacts files; VACUUM deletes obsolete files after retention and can limit time travel. DESCRIBE HISTORY lists operations/users/timestamps. VERSION AS OF queries a snapshot; RESTORE changes current state. Liquid clustering replaces manual partition/Z-ORDER strategy.', D+'delta/')
add([53,177], 'SQL functions', 'CREATE FUNCTION name(args) RETURNS type RETURN expression defines reusable SQL logic. Prefer built-in functions when available; use UDFs for reusable custom logic. A scalar function returns one value per input row.', D+'sql/language-manual/sql-ref-syntax-ddl-create-sql-function')
add([56,147], 'Notebook languages', 'A notebook has a default language, but each cell has one language. Put %sql at the start of a SQL cell in a Python notebook, or use spark.sql(...) in Python. Python variables are not automatically SQL variables.', D+'notebooks/notebooks-code')
add([57,110,145,150,174,217,222], 'Aggregation', 'groupBy(keys).agg(sum("amount").alias("total")) reduces to one row per group. Window functions keep input rows while adding ranks/running metrics. PIVOT turns distinct row values into columns; UNPIVOT reverses that shape.', S+'sql-ref-syntax-qry-select-pivot.html')
add([58,109,270], 'File schemas', 'Parquet is typed, columnar and embeds a schema. CSV is text and needs a schema or inference; disabling type detection leaves columns as strings. Explicit schemas avoid accidental type changes across files.', D+'query/formats/csv')
add([71,123,133,255], 'Auto Loader schema', 'JSON/CSV columns default to strings unless column-type inference or schema hints are enabled. addNewColumns updates the schema then requires a restart; failOnNewColumns waits for intervention; rescue keeps unexpected fields in rescued data.', 'https://learn.microsoft.com/en-us/azure/databricks/ingestion/auto-loader/schema')
add([84,87,131], 'Notifications', 'Job notifications report run events such as failure; SQL alerts evaluate a query-result condition. To notify a team through messaging, configure a webhook destination and attach it to the alert—not just a custom message template.', D+'sql/user/alerts/')
add([132,143,169,171,194,196,199], 'Delta Sharing', 'Delta Sharing provides governed access without exporting full copies. Open sharing supports non-Databricks recipients; Databricks-to-Databricks sharing uses recipient identity. Cross-cloud/region reads can incur network egress charges.', D+'delta-sharing/')
add([136,137,189,208,214,228,242,244,249,262,271,277], 'Automation bundles', 'databricks.yml declares resources and targets in YAML. Use target variables/overrides for dev/test/prod. CLI order: databricks bundle validate → bundle deploy → bundle run <resource-key>. Deploy creates/updates resources; it does not execute the job.', D+'dev-tools/bundles/')
add([139,178,181,186,224,237,266,267,268,269], 'Spark performance', 'Spark UI reveals slow stages, shuffle and task-duration skew. Broadcast a genuinely small join side to avoid its shuffle. collect()/toPandas() bring results to the driver and can exhaust driver memory; executor shuffle failures need partition/skew/memory analysis.', D+'optimizations/spark-ui-guide/')
add([142,184], 'Federation', 'Lakehouse Federation queries external databases through governed connections/foreign catalogs without first copying everything into Delta. Federation is query access; ingestion creates a local persisted copy for downstream processing.', D+'query-federation/')
add([144,152,238], 'Kafka ingestion', 'Use spark.readStream.format("kafka") with kafka.bootstrap.servers and subscribe. Kafka records expose key/value bytes—cast and parse the value using an explicit schema. Checkpoints track offsets; incremental database sync needs CDC or a reliable watermark.', D+'connect/streaming/kafka')
add([149,200,205,215], 'Databricks Connect', 'Write/debug PySpark in your local IDE; DataFrame execution runs on remote Databricks compute. This is not a local copy of the full cluster. Match supported client/runtime versions and configure workspace authentication.', D+'dev-tools/databricks-connect/')
add([153], 'Notebook output', 'Notebook output is separate from dataset storage. Large printed/displayed results can exceed execution output limits; write full data to a table or file and return a small summary. Check the documented limit for the specific execution interface.', D+'jobs/notebook')
add([156], 'Audit logs', 'Audit events are structured JSON records containing fields such as timestamp, service/action, user identity and request details. System audit tables make these events queryable; Delta table history is narrower and describes table operations.', D+'admin/account-settings/audit-logs')
add([161,198,209], 'Catalog discovery', 'Catalog Explorer shows catalogs, schemas and tables, including owners, permissions and lineage. Unity Catalog lineage connects upstream sources to downstream tables and notebooks; table history instead shows operations over time.', D+'data-governance/unity-catalog/data-lineage')
add([162,201], 'Network access', 'Use compute with network access to the source database. A classic customer-VPC cluster can reach private resources when routing, DNS, firewall and credentials allow it; serverless private connectivity requires its supported network configuration.', D+'security/network/')
add([164,166,185], 'Notebook debugging', 'Use the Python debugger/breakpoints to inspect variables at the failing line, and run cells selectively while developing. For Spark work, inspect the execution plan and Spark UI as well—Python control flow and distributed execution are different layers.', D+'notebooks/debugger')
add([172,175,206,218,223,276], 'Repair runs', 'Repair run reruns failed/skipped tasks in an existing multi-task run, preserving successful upstream work. Rerun restarts execution. Check repair eligibility and configuration changes; a single-task failure is normally handled with a rerun.', D+'jobs/repair-job-failures')
add([179], 'File filters', 'pathGlobFilter="*.png" restricts input filenames while preserving partition discovery. A format reader still must match file contents; filtering a suffix does not decode an image. Use recursiveFileLookup only when recursive traversal is needed.', S+'sql-data-sources-generic-options.html')
add([195,216], 'External locations', 'A storage credential represents cloud authentication; an external location binds a cloud path to that credential. Unity Catalog privileges on the location govern creating/accessing external data objects; avoid embedding raw cloud secrets in notebooks.', D+'connect/unity-catalog/cloud-storage/')
add([227,234,247,250,263], 'Lakeflow Connect', 'Managed connectors provide incremental ingestion/CDC for supported databases and SaaS sources into governed Unity Catalog tables. File ingestion uses Auto Loader; Kafka uses streaming. Verify connector-specific OAuth, network and CDC prerequisites.', D+'ingestion/lakeflow-connect/')
add([229,254], 'Deduplication', 'dropDuplicates(["customer_id", "email"]) compares only business keys; no arguments compares every column. It does not promise which non-key row survives. To keep the latest record, use row_number over keys ordered by timestamp descending.', S+'api/python/reference/pyspark.sql/api/pyspark.sql.DataFrame.dropDuplicates.html')
add([230,231], 'Fine-grained security', 'A row-filter SQL function returns a BOOLEAN deciding row visibility; column masks transform sensitive values. Account-group membership can choose policy branches. ABAC applies governed-tag policies centrally, reducing per-table manual assignments.', D+'data-governance/unity-catalog/abac/')
add([236], 'JSON parsing', 'from_json(json_string, schema) converts text into typed structs/arrays; then select nested fields into Silver columns. get_json_object extracts text at a path; repeatedly parsing JSON downstream adds work and weakens schema clarity.', S+'api/python/reference/pyspark.sql/api/pyspark.sql.functions.from_json.html')
add([129,243], 'Run diagnostics', 'Compare run history durations against the baseline, then drill into task durations and Spark UI stages. Separate queue/setup time from execution time; intermittent spikes suggest contention, skew or changing input rather than a constant code regression.', D+'jobs/monitor')
add([246], 'Scheduling cost', 'Choose a trigger interval that leaves enough processing time inside the 15-minute freshness SLA. Small periodic available-now runs can stop compute between arrivals; continuous execution is useful when its lower latency justifies the cost.', D+'jobs/triggers')
missing=[x['id'] for x in q if x['id'] not in notes]
assert not missing, f'Missing GPT notes: {missing}'
for x in q: x['gpt']=notes[x['id']]
(R/'dist/data.json').write_text(json.dumps(q,ensure_ascii=False),encoding='utf-8')
print(f'Built {len(q)} questions with GPT notes; {len(set(n["topic"] for n in notes.values()))} topics.')

